#include <acutest.h>
#include <gkyl_gyrokinetic_priv.h>

static void
step_f(struct gkyl_array *out, double dt, const struct gkyl_array *inp)
{
  gkyl_array_accumulate(gkyl_array_scale(out, dt), 1.0, inp);
}

static void
test_filter_exchange(bool cellwise_const, bool use_gpu)
{
  struct gkyl_gyrokinetic_app *app = gkyl_malloc(sizeof *app);
  memset(app, 0, sizeof *app);
  struct gk_field field = {0};
  app->field = &field;
  app->use_gpu = use_gpu;
  struct gk_species *gks = gkyl_malloc(sizeof *gks);
  memset(gks, 0, sizeof *gks);
  gkyl_cart_modal_gkhybrid(&gks->basis, 1, 2);
  int shape[] = {2, 1, 1};
  gkyl_range_init_from_shape(&gks->local_ext, 3, shape);
  gks->local = gks->local_ext;
  gks->step_f_func = step_f;
  gks->info.damping = (struct gkyl_gyrokinetic_damping){
    .type = GKYL_GK_DAMPING_LOW_PASS_FILTER,
    .rate_const = 2.0,
    .cellwise_const = cellwise_const,
  };
  gk_species_damping_init(app, gks, &gks->damping);
  gk_species_fdot_multiplier_init(app, gks, &gks->fdot_mult);
  int ncomp = gks->basis.num_basis;
  int nbar = gks->damping.fbar->ncomp;
  struct gkyl_array *fin = mkarr(use_gpu, ncomp, 2);
  struct gkyl_array *rhs = mkarr(use_gpu, ncomp, 2);
  struct gkyl_array *buffer = mkarr(use_gpu, ncomp, 2);
  struct gkyl_array *cfl = mkarr(use_gpu, 1, 2);
  struct gkyl_array *fin_ho = mkarr(false, ncomp, 2);
  struct gkyl_array *fbar_ho = mkarr(false, nbar, 2);
  struct gkyl_array *mult_ho = mkarr(false, 1, 2);

  // Exercise enabling, composing, and disabling multipliers without rebuilding damping.
  for (int scenario = 0; scenario < 5; ++scenario) {
    struct gkyl_gyrokinetic_fdot_multiplier inp = {0};
    inp.num_multipliers = scenario == 0 || scenario == 4 ? 0 : scenario == 2 ? 2 : 1;
    for (int k = 0; k < inp.num_multipliers; ++k) {
      inp.multiplier[k].type = GKYL_GK_FDOT_MULTIPLIER_CONSTANT;
      inp.multiplier[k].cellwise_const = true;
      inp.multiplier[k].time_dilation_scale_const = 0.5;
    }
    gk_species_fdot_multiplier_reset(app, 0.0, gks, &gks->fdot_mult, inp);
    gkyl_array_clear(fin, 3.0);
    gkyl_array_clear(gks->damping.fbar, 1.0);
    double decay[2] = {1.0, 1.0};
    double high_decay[2] = {1.0, 1.0};
    const double dt = 0.1, rate = 2.0;
    for (int stage = 0; stage < 8; ++stage) {
      gkyl_array_clear(rhs, 0.0);
      gkyl_array_clear(cfl, 0.0);
      gk_species_damping_advance(
        app, gks, &gks->damping, 0, fin, gks->damping.fbar, buffer, rhs, cfl
      );
      gk_species_fdot_multiplier_advance_times_cfl(app, gks, &gks->fdot_mult, 0, fin, cfl);
      double mult[2] = {pow(0.5, inp.num_multipliers), pow(0.5, inp.num_multipliers)};
      if (scenario == 3) {
        // Supply a cached stage-dependent cell multiplier, including a frozen cell.
        // The fbar update must reuse it, not reconstruct the constant component.
        mult[0] = stage % 2 ? 0.2 : 0.0;
        mult[1] = stage % 2 ? 0.7 : 0.4;
        for (int cell = 0; cell < 2; ++cell) {
          double *val = gkyl_array_fetch(mult_ho, cell);
          val[0] = mult[cell];
        }
        gkyl_array_copy(gks->fdot_mult.multiplier, mult_ho);
      }
      gk_species_fdot_multiplier_advance_times_rate(app, gks, &gks->fdot_mult, 0, fin, rhs);
      gk_species_damping_forward_euler(app, gks, fin, gks->damping.fbar, gks->damping.fbar1, dt);
      gk_species_step_f(gks, rhs, dt, fin);
      gkyl_array_copy(fin, rhs);
      gkyl_array_copy(gks->damping.fbar, gks->damping.fbar1);
      gkyl_array_copy(fin_ho, fin);
      gkyl_array_copy(fbar_ho, gks->damping.fbar);
      for (int cell = 0; cell < 2; ++cell) {
        decay[cell] *= 1.0 - 2.0 * dt * rate * mult[cell];
        high_decay[cell] *= 1.0 - dt * rate * mult[cell];
        const double *fval = gkyl_array_cfetch(fin_ho, cell);
        const double *bar = gkyl_array_cfetch(fbar_ho, cell);
        for (int k = 0; k < nbar; ++k) {
          TEST_CHECK(gkyl_compare(fval[k] + bar[k], 4.0, 1e-13));
          TEST_CHECK(gkyl_compare(fval[k] - bar[k], 2.0 * decay[cell], 1e-13));
        }
        // With p0 storage, higher DG modes damp without a matching fbar mode.
        for (int k = nbar; k < ncomp; ++k) {
          TEST_CHECK(gkyl_compare(fval[k], 3.0 * high_decay[cell], 1e-13));
        }
      }
    }
  }
  gkyl_array_release(fin);
  gkyl_array_release(rhs);
  gkyl_array_release(buffer);
  gkyl_array_release(cfl);
  gkyl_array_release(fin_ho);
  gkyl_array_release(fbar_ho);
  gkyl_array_release(mult_ho);
  gk_species_fdot_multiplier_release(app, &gks->fdot_mult);
  gk_species_damping_release(app, &gks->damping);
  gkyl_free(gks);
  gkyl_free(app);
}

